drawing.css:
.planta{max-width:1180px;margin:0 auto;padding:0 clamp(16px,4vw,48px) 30px}
.planta h2{font:500 15px/1.4 var(--mono);letter-spacing:.1em;text-transform:uppercase;margin:0 0 4px}
.planta .lede{font-size:16px;line-height:1.5;color:var(--ink-2);max-width:90ch;margin:0 0 14px}
.planta .sheet{background:var(--paper);border:1.5px solid var(--ink);box-shadow:6px 6px 0 var(--grid-major);overflow-x:auto}
.planta svg{display:block;width:100%;min-width:900px;height:auto}
.planta .caption{display:flex;justify-content:space-between;gap:12px;flex-wrap:wrap;border:1.5px solid var(--ink);border-top:0;padding:8px 12px;font:10.5px var(--mono);letter-spacing:.08em;text-transform:uppercase;color:var(--ink-2);background:var(--paper)}
.map text{font-family:var(--mono);font-size:13px;letter-spacing:0;fill:var(--ink)}
.map .hdr{font-size:11px;letter-spacing:.12em;fill:var(--ink-2)}.map .sm{font-size:11px}.map .xs{font-size:10px;letter-spacing:.02em}
.map .ttl{font-family:var(--sans);font-weight:700;font-size:15px;letter-spacing:0}
.map a{cursor:pointer}.map a rect,.map a circle{transition:fill .15s,stroke-width .15s}
.map a:hover rect,.map a:focus-visible rect{fill:var(--conc-wash);stroke:var(--conc);stroke-width:2}
.map a.d:hover rect,.map a.d:focus-visible rect{fill:var(--dif-wash);stroke:var(--dif)}
.map a:hover circle.st,.map a:focus-visible circle.st{fill:var(--conc)}
.map a:hover text,.map a:focus-visible text{text-decoration:underline}.map a:focus{outline:none}
.map a:focus-visible rect,.map a:focus-visible circle{stroke-width:3}

@media(max-width:720px) and (orientation:portrait){
  .front-drawing{max-width:100%;overflow:hidden}
  .planta{max-width:100%;box-sizing:border-box}
  .planta .sheet{width:100%;max-width:100%;box-sizing:border-box;overflow-x:auto;overscroll-behavior-x:contain}
  .planta svg{width:900px;min-width:900px;max-width:none}
}

@media(max-width:720px) and (orientation:portrait){.front-art-desktop svg.map{width:100%;height:auto}}
